const form=document.querySelector('#smtp-form'),message=document.querySelector('#smtp-message');async function api(options={}){const response=await fetch('/api/admin/smtp-settings',{cache:'no-store',...options}),data=await response.json().catch(()=>({}));if(response.status===401){location.href='/admin/';throw new Error('Sessão expirada.')}if(!response.ok)throw new Error(data.error||'Não foi possível concluir.');return data}function values(){const v=Object.fromEntries(new FormData(form));v.porta=Number(v.porta);v.seguro=v.seguro==='true';v.ativo=v.ativo==='true';return v}async function load(){try{const {configuracao:c}=await api();for(const name of ['host','porta','usuario','remetenteNome','remetenteEmail','responderPara'])if(form.elements[name])form.elements[name].value=c[name]??'';form.elements.seguro.value=String(c.seguro);form.elements.ativo.value=String(c.ativo);form.elements.senha.placeholder=c.senhaConfigurada?'Configurada · deixe vazio para manter':'Informe a senha'}catch(error){message.textContent=error.message}}form.onsubmit=async e=>{e.preventDefault();message.textContent='';try{await api({method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(values())});message.textContent='Configuração salva com segurança.';form.elements.senha.value='';await load()}catch(error){message.textContent=error.message}};document.querySelector('#test').onclick=async()=>{message.textContent='Testando conexão…';try{const v=values();v.testar=true;const data=await api({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(v)});message.textContent=data.mensagem}catch(error){message.textContent=error.message}};load();
